// Input: JSON field with key "preview_file"
const htmlContent = $json.preview_file;

return [
  {
    json: {},
    binary: {
      data: {
        data: Buffer.from(htmlContent, "utf8").toString("base64"),
        mimeType: "text/html",
        fileName: "preview.html"
      }
    }
  }
];

const webhookData = $('Webhook').first().json.body;       // Incoming payload
const settings = $('Get Settings').first().json;          // Settings object

// Determine assignment type
let assignmentSegment = "";
if (webhookData.action_name === "Create Posts") {
  assignmentSegment = "Your assignment is to create complete, engaging post content for the given topic. Write new posts from scratch that align with the brand voice and current campaign context.";
} else if (webhookData.action_name === "Update Posts") {
  assignmentSegment = "Your assignment is to update existing post content based on user feedback or new information. Improve clarity, tone, or structure while maintaining the core idea and brand style.";
} else {
  assignmentSegment = "Your assignment is to produce social media content as per provided context.";
}

// Build dynamic per-platform constraints
const platformInstructions = [];

if (webhookData.action_for_instagram === false) {
  platformInstructions.push("- Do **not** write Instagram content; leave the 'Instagram' field empty but keep the key present in JSON.");
}
if (webhookData.action_for_facebook === false) {
  platformInstructions.push("- Do **not** write Facebook content; leave the 'Facebook' field empty but keep the key present in JSON.");
}
if (webhookData.action_for_linkedin === false) {
  platformInstructions.push("- Do **not** write LinkedIn content; leave the 'LinkedIn' field empty but keep the key present in JSON.");
}

// Build final prompt
const prompt = `
# Role
You are a professional Social Media Copywriter specializing in crafting high-quality posts for Instagram, Facebook, and LinkedIn.  
Your goal is to produce complete, engaging, and brand-consistent text content for these platforms.

---

## Assignment
${assignmentSegment}

---

## Platform Behaviour
- Instagram and Facebook posts share identical text and hashtags.  
- LinkedIn post is distinct, written in a more professional, insight-driven tone.  
- Keep formatting natural for each platform (no hashtags in LinkedIn text).

${
  platformInstructions.length > 0
    ? `\n### Platform-Specific Instructions\n${platformInstructions.join('\n')}\n`
    : ''
}

---

## Style and Tone
**Instagram/Facebook Prompt:** ${settings.prompt_instagram || ""}
**LinkedIn Prompt:** ${settings.prompt_linkedin || ""}
**Tone of Voice:** ${settings.tone_of_voice || ""}
**Target Audience:** ${settings.target_audience || ""}
**Product / Topic:** ${settings.product || ""}
**Language:** ${settings.language || ""}

---

## Formatting Rules
- Write naturally, without emojis unless clearly appropriate.  
- Use clear paragraphs for readability.  
- Ensure professional grammar and coherence.  
- Avoid meta explanations, markdown, or system notes — output pure text content.  

---

## Output JSON Structure
Return the result **only** in this JSON format. No other fields. No follow up question. Answer to the best of your ability in **only** the expected format:

\`\`\`json
{
  "Facebook": "string",
  "Instagram": "string",
  "LinkedIn": "string",
  "Hashtags": "Hashtag1, Hashtag2, Hashtag3"
}
\`\`\`

- The keys **must always be present** in the JSON output.  
- If any "action_for_<platform>" value is false, output an empty string ("") for that platform's value.  
- The JSON must be valid and parsable.
`;

// Return to n8n
return [
  {
    json: {
      system_prompt: prompt.trim(),
      action_name: webhookData.action_name,
    },
  },
];

